// Example demonstrating safe parsing vs vulnerable patterns
const crypto = require('crypto');

const SECRET_KEY = 'super-secret-key-change-me';

// Generate a signed session payload
function createSignedSession(dataObj) {
  const serialized = JSON.stringify(dataObj);
  const signature = crypto
    .createHmac('sha256', SECRET_KEY)
    .update(serialized)
    .digest('hex');
  return Buffer.from(JSON.stringify({ data: serialized, sig: signature })).toString('base64');
}

// Securely verify and parse session data
function parseSignedSession(base64Token) {
  try {
    const decoded = JSON.parse(Buffer.from(base64Token, 'base64').toString('utf8'));
    const expectedSig = crypto
      .createHmac('sha256', SECRET_KEY)
      .update(decoded.data)
      .digest('hex');

    if (expectedSig !== decoded.sig) {
      throw new Error('Signature mismatch! Data tampered.');
    }
    return JSON.parse(decoded.data);
  } catch (err) {
    console.error('Deserialization security error:', err.message);
    return null;
  }
}

